# -*- coding: utf-8 -*-
def L(code, hreflang, path, native, **k):
    d = dict(code=code, hreflang=hreflang, dir='ltr', path=path, native=native, demos=['ar', 'fa', 'ur', 'he']); d.update(k); return d

TR = L('tr', 'tr', 'tr/', 'Türkçe',
 title='RTL Text Fixer – Kopuk ve Ters Arapça, Farsça, Urduca, İbranice Metni Düzeltin (Windows)',
 desc='Premiere Pro, After Effects, Unity veya Blender’da Arapça harfler ayrık ve ters mi görünüyor? RTL Text Fixer, Arapça, Farsça, Urduca ve İbranice metni sağdan sola desteği olmayan uygulamalarda doğru görünecek şekilde dönüştürür.',
 h1='Sağdan sola desteklemeyen uygulamalarda Arapça ve İbranice metni doğru gösterin',
 lead='<b>RTL Text Fixer</b> bir Windows 10/11 uygulamasıdır. Birçok video, hareketli grafik, 3B, oyun motoru ve tasarım aracı Arapçayı ayrık harflerle ve ters sırada, İbranice’yi de ters gösterir. Metni uygulamaya yapıştırıp sonucu kopyalayın: harfler birleşir (Unicode sunum biçimleri) ve metin görsel sıraya konur. Ya da metni herhangi bir yerde kopyalayın, <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd>’ye basın ve yapıştırın.',
 demo_title='Önce ve sonra', demo_caption='Sağdan sola desteği olmayan bir uygulamanın görüntüsünün benzetimi (harfler soldan sağa, birleştirilmeden çizilir). Kırmızı: olduğu gibi yapıştırılan metin. Yeşil: RTL Text Fixer sonrası aynı metin — uygulamanın gerçek motorunun çıktısı.',
 how_title='Nasıl çalışır', how=['Metni kutuya yapıştırın veya yazın; yazı sistemi ve dil otomatik algılanır.', 'Önizleme, sonucun RTL desteği olmayan uygulamada nasıl görüneceğini tam olarak gösterir. <b>Sonucu kopyala</b>’ya basıp projenize yapıştırın.', 'Pencereyi açmadan: metni kopyalayın, <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd>’ye basın ve yapıştırın. Tekrar basınca özgün metin geri gelir.'],
 shot_alt='RTL Text Fixer penceresi: Arapça metin ve düzeltilmiş metnin önizlemesi',
 langs_title='Desteklenen diller', langs='<b>Arap alfabesiyle yazılan diller</b> (harf birleştirme ve sıralama): Arapça, Farsça, Urduca, Kürtçe (Sorani), Peştuca, Sindhi, Uygurca; lam-elif bitişikleri dahil. <b>İbranice ve Yidiş</b> (yalnızca sıralama). Metindeki sayılar ve Latin harfli kelimeler doğru sırada kalır.',
 features_title='Özellikler', features=['Bitişik harf biçimleri ve lam-elif', 'Görsel sıra; sayılar ve Latin kelimeler doğru yerde, parantezler aynalanır', 'Otomatik yazı ve dil algılama', 'Harekeler: koru, kaldır veya ayrı biçimler', 'Çok satırlı metin, satır sırasını ters çevirme ve satır kaydırma', 'Geri alma modu: düzeltilmiş metni normal metne çevirir', 'Pano kısayolu (Ctrl+Shift+R) ve sistem tepsisi simgesi', '12 dilde arayüz (Türkçe dahil)', 'Çevrimdışı: hesap, reklam ve izleme yok'],
 limits_title='Sınırlamalar', limits=['Yalnızca Windows 10 (1809 ve sonrası) ve Windows 11.', 'Unicode’da bitişik biçimi olmayan harfler (ör. Kürtçe ڵ ڕ ێ) ayrık görünür.', 'Hedef uygulamanın yazı tipi Arapça sunum biçimlerini içermelidir (Arial, Tahoma, Segoe UI içerir).', 'Sonuç görüntüleme içindir; uzun metinlerde satır kaydırma seçeneğini kullanın.'],
 faq_title='Sık sorulan sorular',
 faq=[('Premiere Pro’da Arapça harfler neden ayrık ve ters görünüyor?', 'Arapça harf birleştirmeyi ve çift yönlü metni desteklemeyen programlar her harfi ayrı ve soldan sağa çizer. Yeni Premiere Pro sürümlerinde Orta Doğu metin motoru açılabilir; açılamıyorsa metni RTL Text Fixer ile dönüştürüp başlığa yapıştırın.'),
      ('After Effects’te Farsça metin ters çıkıyor, ne yapmalıyım?', 'Sürümünüzde varsa Orta Doğu ve Güney Asya metin motorunu etkinleştirin; yoksa metni RTL Text Fixer ile dönüştürün.'),
      ('Unity’de İbranice metin ters görünüyor, nasıl düzeltilir?', 'Unity’nin standart metin bileşenleri sağdan sola metni sıralamaz. RTL Text Fixer ile dönüştürülmüş metni Text veya TextMeshPro alanına yapıştırın.'),
      ('Sayılar ve İngilizce kelimeler doğru kalıyor mu?', 'Evet, Unicode Çift Yönlü Algoritması’na göre.'),
      ('Metnim bir yere gönderiliyor mu?', 'Hayır. Uygulama tamamen çevrimdışı çalışır.'),
      ('Nereden edinebilirim?', 'RTL Text Fixer, Microsoft Store’da ücretli bir uygulama olacak. Mağaza sayfası henüz yayında değil; yayınlanınca bağlantı buraya eklenecek.')],
 store_note='Microsoft Store’da yakında — mağaza bağlantısı yayınlandığında buraya eklenecek.', other='Diğer diller', privacy='Gizlilik politikası', support='Destek',
 source_note='Harf birleştirme ve yön verileri Unicode Karakter Veritabanı’ndan (15.1) alınmıştır.')

RU = L('ru', 'ru', 'ru/', 'Русский',
 title='RTL Text Fixer – исправление разорванного и перевёрнутого арабского, персидского, урду и иврита (Windows)',
 desc='Арабские буквы разорваны и идут задом наперёд в Premiere Pro, After Effects, Unity или Blender? RTL Text Fixer для Windows преобразует арабский, персидский, урду и иврит так, чтобы программы без поддержки RTL показывали текст правильно.',
 h1='Арабский и иврит — правильно в программах без поддержки письма справа налево',
 lead='<b>RTL Text Fixer</b> — приложение для Windows 10/11. Многие программы для видео, моушн-дизайна, 3D, игровые движки и графические редакторы показывают арабский как отдельные буквы в обратном порядке, а иврит — задом наперёд. Вставьте текст в приложение и скопируйте результат: буквы соединяются (формы представления Unicode), а текст переставляется в визуальный порядок. Или скопируйте текст где угодно, нажмите <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> и вставьте.',
 demo_title='До и после', demo_caption='Имитация отображения в программе без поддержки письма справа налево (символы рисуются слева направо без соединения). Красным: текст как есть. Зелёным: тот же текст после RTL Text Fixer — результат реального движка приложения.',
 how_title='Как это работает', how=['Вставьте или введите текст; письменность и язык определяются автоматически.', 'Предпросмотр показывает, как результат будет выглядеть в программе без поддержки RTL. Нажмите <b>Копировать результат</b> и вставьте в проект.', 'Без окна: скопируйте текст, нажмите <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> и вставьте. Повторное нажатие возвращает исходный текст.'],
 shot_alt='Окно RTL Text Fixer: арабский текст и предпросмотр исправленного текста',
 langs_title='Поддерживаемые языки', langs='<b>Языки с арабской письменностью</b> (соединение букв и порядок): арабский, персидский, урду, курдский (сорани), пушту, синдхи, уйгурский, с лигатурами лям-алиф. <b>Иврит и идиш</b> (только порядок). Числа и латинские слова сохраняют правильный порядок.',
 features_title='Возможности', features=['Соединённые формы букв и лигатуры лям-алиф', 'Визуальный порядок: числа и латиница на своих местах, скобки отражаются', 'Автоопределение письменности и языка', 'Огласовки: оставить, удалить или отдельные формы', 'Многострочный текст, обратный порядок строк, перенос строк', 'Обратное преобразование в обычный текст', 'Горячая клавиша для буфера (Ctrl+Shift+R) и значок в трее', 'Интерфейс на 12 языках, включая русский', 'Без интернета, аккаунта, рекламы и телеметрии'],
 limits_title='Ограничения', limits=['Только Windows 10 (1809 и новее) и Windows 11.', 'Буквы без соединённых форм в Unicode (например, курдские ڵ ڕ ێ) остаются несоединёнными.', 'Шрифт в целевой программе должен содержать арабские формы представления (Arial, Tahoma, Segoe UI — содержат).', 'Результат предназначен для отображения; для длинного текста используйте перенос строк.'],
 faq_title='Частые вопросы',
 faq=[('Почему арабские буквы в Premiere Pro разорваны и идут в обратном порядке?', 'Программы без поддержки арабского письма и двунаправленного текста рисуют каждую букву в изолированной форме слева направо. В новых версиях Premiere Pro можно включить ближневосточный текстовый движок; если это невозможно, преобразуйте текст в RTL Text Fixer и вставьте результат.'),
      ('Иврит в Unity отображается задом наперёд — что делать?', 'Стандартные текстовые компоненты Unity не переставляют текст справа налево. Вставьте в поле Text или TextMeshPro текст, преобразованный RTL Text Fixer.'),
      ('Как написать по-арабски в Blender?', 'Текстовые объекты Blender не соединяют арабские буквы. Преобразуйте текст в RTL Text Fixer и выберите шрифт с арабскими формами представления.'),
      ('Числа и английские слова остаются на месте?', 'Да, согласно двунаправленному алгоритму Unicode.'),
      ('Отправляется ли мой текст куда-либо?', 'Нет. Приложение работает полностью офлайн.'),
      ('Где его получить?', 'RTL Text Fixer будет платным приложением в Microsoft Store. Страница в магазине ещё не опубликована; ссылка появится здесь после публикации.')],
 store_note='Скоро в Microsoft Store — ссылка появится здесь после публикации.', other='Другие языки', privacy='Политика конфиденциальности', support='Поддержка',
 source_note='Данные о соединении и направлении — из базы символов Unicode (версия 15.1).')

ES = L('es', 'es', 'es/', 'Español',
 title='RTL Text Fixer – Corrige texto árabe, persa, urdu y hebreo desconectado o invertido (Windows)',
 desc='¿Letras árabes separadas y al revés en Premiere Pro, After Effects, Unity o Blender? RTL Text Fixer para Windows convierte texto árabe, persa, urdu y hebreo para que las aplicaciones sin soporte de derecha a izquierda lo muestren bien.',
 h1='Texto árabe y hebreo correcto en aplicaciones sin soporte de derecha a izquierda',
 lead='<b>RTL Text Fixer</b> es una aplicación para Windows 10/11. Muchas herramientas de vídeo, motion graphics, 3D, motores de juegos y diseño muestran el árabe con letras separadas en orden inverso y el hebreo al revés. Pega tu texto y copia el resultado: las letras se unen (formas de presentación Unicode) y el texto pasa a orden visual. O copia texto en cualquier sitio, pulsa <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> y pega.',
 demo_title='Antes y después', demo_caption='Simulación de una aplicación sin soporte de derecha a izquierda (glifos dibujados de izquierda a derecha, sin unir). Rojo: texto pegado tal cual. Verde: el mismo texto tras RTL Text Fixer, generado por el motor real de la aplicación.',
 how_title='Cómo funciona', how=['Pega o escribe el texto; la escritura y el idioma se detectan automáticamente.', 'La vista previa muestra cómo se verá en una aplicación sin soporte RTL. Pulsa <b>Copiar resultado</b> y pégalo en tu proyecto.', 'Sin abrir la ventana: copia el texto, pulsa <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> y pega. Vuelve a pulsarlo para recuperar el original.'],
 shot_alt='Ventana de RTL Text Fixer: texto árabe y vista previa del texto corregido',
 langs_title='Idiomas compatibles', langs='<b>Idiomas con escritura árabe</b> (unión de letras y orden): árabe, persa, urdu, kurdo (sorani), pastún, sindhi y uigur, con ligaduras lam-alif. <b>Hebreo e ídish</b> (solo orden). Los números y las palabras latinas mantienen el orden correcto.',
 features_title='Características', features=['Letras unidas y ligaduras lam-alif', 'Orden visual con números y palabras latinas en su sitio; paréntesis reflejados', 'Detección automática de escritura e idioma', 'Diacríticos: mantener, quitar o formas separadas', 'Texto multilínea, orden de líneas invertido y ajuste de líneas', 'Modo deshacer: vuelve al texto normal', 'Atajo de portapapeles (Ctrl+Shift+R) e icono en la bandeja', 'Interfaz en 12 idiomas, incluido el español', 'Sin conexión, sin cuenta, anuncios ni telemetría'],
 limits_title='Limitaciones', limits=['Solo Windows 10 (1809 o posterior) y Windows 11.', 'Las letras sin formas unidas en Unicode (p. ej. kurdo ڵ ڕ ێ) quedan sin unir.', 'La fuente de la aplicación de destino debe incluir las formas de presentación árabes (Arial, Tahoma y Segoe UI las incluyen).', 'El resultado es para mostrar; con textos largos usa el ajuste de líneas.'],
 faq_title='Preguntas frecuentes',
 faq=[('¿Por qué las letras árabes salen separadas y al revés en Premiere Pro?', 'Los programas sin soporte de escritura árabe y texto bidireccional dibujan cada letra aislada de izquierda a derecha. Las versiones recientes de Premiere Pro tienen un motor de texto para Oriente Medio; si no puedes usarlo, convierte el texto con RTL Text Fixer y pega el resultado.'),
      ('El hebreo sale al revés en Unity, ¿cómo lo arreglo?', 'Los componentes de texto estándar de Unity no reordenan el texto de derecha a izquierda. Pega en Text o TextMeshPro el texto convertido con RTL Text Fixer.'),
      ('¿Cómo escribo en árabe en Blender?', 'Los objetos de texto de Blender no unen las letras árabes. Convierte el texto con RTL Text Fixer y usa una fuente con formas de presentación árabes.'),
      ('¿Los números y las palabras en inglés quedan en su sitio?', 'Sí, según el algoritmo bidireccional de Unicode.'),
      ('¿Se envía mi texto a algún sitio?', 'No. La aplicación funciona totalmente sin conexión.'),
      ('¿Dónde la consigo?', 'RTL Text Fixer será una aplicación de pago en Microsoft Store. La página de la tienda aún no está publicada; el enlace se añadirá aquí al publicarse.')],
 store_note='Próximamente en Microsoft Store: el enlace se añadirá aquí al publicarse.', other='Otros idiomas', privacy='Política de privacidad', support='Soporte',
 source_note='Los datos de unión y dirección proceden de la base de datos de caracteres Unicode (versión 15.1).')

FR = L('fr', 'fr', 'fr/', 'Français',
 title='RTL Text Fixer – Corriger le texte arabe, persan, ourdou et hébreu déconnecté ou inversé (Windows)',
 desc='Lettres arabes séparées et inversées dans Premiere Pro, After Effects, Unity ou Blender ? RTL Text Fixer pour Windows convertit le texte arabe, persan, ourdou et hébreu pour que les applications sans prise en charge de la droite vers la gauche l’affichent correctement.',
 h1='Du texte arabe et hébreu correct dans les applications sans prise en charge RTL',
 lead='<b>RTL Text Fixer</b> est une application pour Windows 10/11. Beaucoup d’outils de vidéo, de motion design, de 3D, de moteurs de jeu et de design affichent l’arabe en lettres séparées dans l’ordre inverse, et l’hébreu à l’envers. Collez votre texte et copiez le résultat : les lettres sont liées (formes de présentation Unicode) et le texte est mis dans l’ordre visuel. Ou copiez du texte n’importe où, appuyez sur <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> et collez.',
 demo_title='Avant et après', demo_caption='Simulation d’une application sans prise en charge de la droite vers la gauche (glyphes dessinés de gauche à droite, sans liaison). Rouge : texte collé tel quel. Vert : le même texte après RTL Text Fixer, produit par le moteur réel de l’application.',
 how_title='Fonctionnement', how=['Collez ou saisissez le texte ; l’écriture et la langue sont détectées automatiquement.', 'L’aperçu montre le résultat tel qu’il apparaîtra dans une application sans prise en charge RTL. Cliquez sur <b>Copier le résultat</b> et collez-le dans votre projet.', 'Sans ouvrir la fenêtre : copiez le texte, appuyez sur <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> et collez. Appuyez à nouveau pour retrouver l’original.'],
 shot_alt='Fenêtre de RTL Text Fixer : texte arabe et aperçu du texte corrigé',
 langs_title='Langues prises en charge', langs='<b>Langues à écriture arabe</b> (liaison des lettres et ordre) : arabe, persan, ourdou, kurde (sorani), pachto, sindhi et ouïghour, avec ligatures lam-alif. <b>Hébreu et yiddish</b> (ordre uniquement). Les nombres et les mots latins gardent le bon ordre.',
 features_title='Fonctionnalités', features=['Lettres liées et ligatures lam-alif', 'Ordre visuel avec nombres et mots latins à leur place ; parenthèses inversées', 'Détection automatique de l’écriture et de la langue', 'Signes diacritiques : conserver, supprimer ou formes séparées', 'Texte multiligne, ordre des lignes inversé et retour à la ligne', 'Mode annulation : retour au texte normal', 'Raccourci presse-papiers (Ctrl+Shift+R) et icône de notification', 'Interface en 12 langues, dont le français', 'Hors ligne, sans compte, publicité ni télémétrie'],
 limits_title='Limites', limits=['Windows 10 (1809 ou plus récent) et Windows 11 uniquement.', 'Les lettres sans formes liées dans Unicode (p. ex. kurde ڵ ڕ ێ) restent non liées.', 'La police de l’application cible doit contenir les formes de présentation arabes (Arial, Tahoma et Segoe UI les contiennent).', 'Le résultat sert à l’affichage ; pour un texte long, utilisez le retour à la ligne.'],
 faq_title='Questions fréquentes',
 faq=[('Pourquoi les lettres arabes sont-elles séparées et inversées dans Premiere Pro ?', 'Les logiciels sans prise en charge de l’écriture arabe et du texte bidirectionnel dessinent chaque lettre isolée de gauche à droite. Les versions récentes de Premiere Pro proposent un moteur de texte pour le Moyen-Orient ; sinon, convertissez le texte avec RTL Text Fixer et collez le résultat.'),
      ('L’hébreu s’affiche à l’envers dans Unity : que faire ?', 'Les composants de texte standard d’Unity ne réordonnent pas le texte de droite à gauche. Collez dans Text ou TextMeshPro le texte converti par RTL Text Fixer.'),
      ('Comment écrire en arabe dans Blender ?', 'Les objets texte de Blender ne lient pas les lettres arabes. Convertissez le texte avec RTL Text Fixer et choisissez une police contenant les formes de présentation arabes.'),
      ('Les nombres et les mots anglais restent-ils à leur place ?', 'Oui, selon l’algorithme bidirectionnel Unicode.'),
      ('Mon texte est-il envoyé quelque part ?', 'Non. L’application fonctionne entièrement hors ligne.'),
      ('Où l’obtenir ?', 'RTL Text Fixer sera une application payante dans le Microsoft Store. La page n’est pas encore publiée ; le lien sera ajouté ici dès sa publication.')],
 store_note='Bientôt dans le Microsoft Store : le lien sera ajouté ici à la publication.', other='Autres langues', privacy='Politique de confidentialité', support='Assistance',
 source_note='Les données de liaison et de direction proviennent de la base de caractères Unicode (version 15.1).')

DE = L('de', 'de', 'de/', 'Deutsch',
 title='RTL Text Fixer – Getrennten und umgedrehten arabischen, persischen, Urdu- und hebräischen Text reparieren (Windows)',
 desc='Arabische Buchstaben getrennt und rückwärts in Premiere Pro, After Effects, Unity oder Blender? RTL Text Fixer für Windows wandelt arabischen, persischen, Urdu- und hebräischen Text so um, dass Programme ohne Rechts-nach-links-Unterstützung ihn richtig anzeigen.',
 h1='Arabischer und hebräischer Text richtig in Programmen ohne RTL-Unterstützung',
 lead='<b>RTL Text Fixer</b> ist eine App für Windows 10/11. Viele Video-, Motion-Design-, 3D-, Game-Engine- und Design-Programme zeigen Arabisch als einzelne Buchstaben in umgekehrter Reihenfolge und Hebräisch rückwärts. Text einfügen und das Ergebnis kopieren: Die Buchstaben werden verbunden (Unicode-Präsentationsformen) und der Text in visuelle Reihenfolge gebracht. Oder Text irgendwo kopieren, <kbd>Strg</kbd>+<kbd>Umschalt</kbd>+<kbd>R</kbd> drücken und einfügen.',
 demo_title='Vorher und nachher', demo_caption='Simulation eines Programms ohne Rechts-nach-links-Unterstützung (Zeichen von links nach rechts, unverbunden gezeichnet). Rot: Text unverändert eingefügt. Grün: derselbe Text nach RTL Text Fixer – erzeugt von der echten Engine der App.',
 how_title='So funktioniert es', how=['Text einfügen oder eingeben; Schrift und Sprache werden automatisch erkannt.', 'Die Vorschau zeigt, wie das Ergebnis in einem Programm ohne RTL-Unterstützung aussieht. <b>Ergebnis kopieren</b> und ins Projekt einfügen.', 'Ohne Fenster: Text kopieren, <kbd>Strg</kbd>+<kbd>Umschalt</kbd>+<kbd>R</kbd> drücken und einfügen. Erneut drücken stellt das Original wieder her.'],
 shot_alt='Fenster von RTL Text Fixer: arabischer Text und Vorschau des umgewandelten Textes',
 langs_title='Unterstützte Sprachen', langs='<b>Sprachen in arabischer Schrift</b> (Verbinden und Ordnen): Arabisch, Persisch, Urdu, Kurdisch (Sorani), Paschtu, Sindhi, Uigurisch, mit Lam-Alif-Ligaturen. <b>Hebräisch und Jiddisch</b> (nur Reihenfolge). Zahlen und lateinische Wörter behalten die richtige Reihenfolge.',
 features_title='Funktionen', features=['Verbundene Buchstabenformen und Lam-Alif-Ligaturen', 'Visuelle Reihenfolge mit Zahlen und lateinischen Wörtern an der richtigen Stelle; gespiegelte Klammern', 'Automatische Schrift- und Spracherkennung', 'Diakritika: behalten, entfernen oder Einzelformen', 'Mehrzeiliger Text, umgekehrte Zeilenreihenfolge und Zeilenumbruch', 'Rückwandlung in normalen Text', 'Zwischenablage-Tastenkürzel (Strg+Umschalt+R) und Infobereich-Symbol', 'Oberfläche in 12 Sprachen, auch Deutsch', 'Offline, ohne Konto, Werbung oder Telemetrie'],
 limits_title='Einschränkungen', limits=['Nur Windows 10 (1809 oder neuer) und Windows 11.', 'Buchstaben ohne verbundene Formen in Unicode (z. B. kurdisch ڵ ڕ ێ) bleiben unverbunden.', 'Die Schrift im Zielprogramm muss arabische Präsentationsformen enthalten (Arial, Tahoma, Segoe UI enthalten sie).', 'Das Ergebnis dient der Anzeige; bei langen Texten den Zeilenumbruch nutzen.'],
 faq_title='Häufige Fragen',
 faq=[('Warum sind arabische Buchstaben in Premiere Pro getrennt und rückwärts?', 'Programme ohne Unterstützung für arabische Schrift und bidirektionalen Text zeichnen jeden Buchstaben isoliert von links nach rechts. Neuere Premiere-Pro-Versionen haben eine Text-Engine für den Nahen Osten; ist sie nicht nutzbar, den Text mit RTL Text Fixer umwandeln und einfügen.'),
      ('Hebräisch wird in Unity rückwärts angezeigt – was tun?', 'Die Standard-Textkomponenten von Unity ordnen Rechts-nach-links-Text nicht um. Den mit RTL Text Fixer umgewandelten Text in Text oder TextMeshPro einfügen.'),
      ('Wie schreibe ich Arabisch in Blender?', 'Textobjekte in Blender verbinden arabische Buchstaben nicht. Den Text mit RTL Text Fixer umwandeln und eine Schrift mit arabischen Präsentationsformen wählen.'),
      ('Bleiben Zahlen und englische Wörter an ihrem Platz?', 'Ja, nach dem bidirektionalen Algorithmus von Unicode.'),
      ('Wird mein Text irgendwohin gesendet?', 'Nein. Die App arbeitet komplett offline.'),
      ('Wo bekomme ich die App?', 'RTL Text Fixer wird eine kostenpflichtige App im Microsoft Store. Die Store-Seite ist noch nicht veröffentlicht; der Link folgt hier nach der Veröffentlichung.')],
 store_note='Demnächst im Microsoft Store – der Link wird hier nach der Veröffentlichung ergänzt.', other='Weitere Sprachen', privacy='Datenschutzerklärung', support='Support',
 source_note='Verbindungs- und Richtungsdaten stammen aus der Unicode-Zeichendatenbank (Version 15.1).')

PT = L('pt-BR', 'pt-BR', 'pt-br/', 'Português (Brasil)',
 title='RTL Text Fixer – Corrija texto em árabe, persa, urdu e hebraico desconectado ou invertido (Windows)',
 desc='Letras árabes separadas e invertidas no Premiere Pro, After Effects, Unity ou Blender? O RTL Text Fixer para Windows converte texto em árabe, persa, urdu e hebraico para que aplicativos sem suporte à escrita da direita para a esquerda o exibam corretamente.',
 h1='Texto em árabe e hebraico correto em aplicativos sem suporte RTL',
 lead='O <b>RTL Text Fixer</b> é um aplicativo para Windows 10/11. Muitas ferramentas de vídeo, motion graphics, 3D, motores de jogos e design mostram o árabe com letras separadas e em ordem invertida, e o hebraico ao contrário. Cole o texto e copie o resultado: as letras são conectadas (formas de apresentação Unicode) e o texto vai para a ordem visual. Ou copie o texto em qualquer lugar, pressione <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> e cole.',
 demo_title='Antes e depois', demo_caption='Simulação de um aplicativo sem suporte à escrita da direita para a esquerda (glifos desenhados da esquerda para a direita, sem ligação). Vermelho: texto colado como está. Verde: o mesmo texto após o RTL Text Fixer, gerado pelo motor real do aplicativo.',
 how_title='Como funciona', how=['Cole ou digite o texto; a escrita e o idioma são detectados automaticamente.', 'A pré-visualização mostra como o resultado vai aparecer num aplicativo sem suporte RTL. Clique em <b>Copiar resultado</b> e cole no seu projeto.', 'Sem abrir a janela: copie o texto, pressione <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> e cole. Pressione de novo para voltar ao original.'],
 shot_alt='Janela do RTL Text Fixer: texto em árabe e pré-visualização do texto corrigido',
 langs_title='Idiomas suportados', langs='<b>Idiomas com escrita árabe</b> (ligação das letras e ordem): árabe, persa, urdu, curdo (sorani), pashto, sindi e uigur, com ligaduras lam-alif. <b>Hebraico e iídiche</b> (só a ordem). Números e palavras latinas mantêm a ordem correta.',
 features_title='Recursos', features=['Letras conectadas e ligaduras lam-alif', 'Ordem visual com números e palavras latinas no lugar certo; parênteses espelhados', 'Detecção automática de escrita e idioma', 'Diacríticos: manter, remover ou formas separadas', 'Texto com várias linhas, ordem das linhas invertida e quebra de linha', 'Modo desfazer: volta ao texto normal', 'Atalho da área de transferência (Ctrl+Shift+R) e ícone na bandeja', 'Interface em 12 idiomas, incluindo português', 'Offline, sem conta, anúncios ou telemetria'],
 limits_title='Limitações', limits=['Somente Windows 10 (1809 ou posterior) e Windows 11.', 'Letras sem formas conectadas no Unicode (ex.: curdo ڵ ڕ ێ) ficam sem ligação.', 'A fonte do aplicativo de destino precisa ter as formas de apresentação árabes (Arial, Tahoma e Segoe UI têm).', 'O resultado é para exibição; em textos longos use a quebra de linha.'],
 faq_title='Perguntas frequentes',
 faq=[('Por que as letras árabes aparecem separadas e invertidas no Premiere Pro?', 'Programas sem suporte à escrita árabe e a texto bidirecional desenham cada letra isolada, da esquerda para a direita. Versões recentes do Premiere Pro têm um motor de texto para o Oriente Médio; se não puder usá-lo, converta o texto com o RTL Text Fixer e cole o resultado.'),
      ('O hebraico aparece ao contrário no Unity. Como corrigir?', 'Os componentes de texto padrão do Unity não reordenam texto da direita para a esquerda. Cole no Text ou TextMeshPro o texto convertido pelo RTL Text Fixer.'),
      ('Como escrever em árabe no Blender?', 'Os objetos de texto do Blender não conectam as letras árabes. Converta o texto com o RTL Text Fixer e use uma fonte com formas de apresentação árabes.'),
      ('Números e palavras em inglês ficam no lugar?', 'Sim, de acordo com o algoritmo bidirecional do Unicode.'),
      ('Meu texto é enviado para algum lugar?', 'Não. O aplicativo funciona totalmente offline.'),
      ('Onde consigo o aplicativo?', 'O RTL Text Fixer será um aplicativo pago na Microsoft Store. A página da loja ainda não foi publicada; o link será adicionado aqui assim que for.')],
 store_note='Em breve na Microsoft Store — o link será adicionado aqui na publicação.', other='Outros idiomas', privacy='Política de privacidade', support='Suporte',
 source_note='Os dados de ligação e direção vêm do banco de dados de caracteres Unicode (versão 15.1).')

HI = L('hi', 'hi', 'hi/', 'हिन्दी',
 title='RTL Text Fixer – टूटे और उलटे अरबी, फ़ारसी, उर्दू और हिब्रू टेक्स्ट को ठीक करें (Windows)',
 desc='Premiere Pro, After Effects, Unity या Blender में उर्दू या अरबी अक्षर अलग-अलग और उलटे दिखते हैं? Windows के लिए RTL Text Fixer अरबी, फ़ारसी, उर्दू और हिब्रू टेक्स्ट को इस तरह बदलता है कि दाएँ-से-बाएँ समर्थन के बिना ऐप्स में यह सही दिखे।',
 h1='दाएँ-से-बाएँ समर्थन के बिना ऐप्स में उर्दू, अरबी और हिब्रू टेक्स्ट सही दिखाएँ',
 lead='<b>RTL Text Fixer</b> Windows 10/11 का ऐप है। कई वीडियो, मोशन ग्राफ़िक्स, 3D, गेम इंजन और डिज़ाइन टूल अरबी लिपि को अलग-अलग अक्षरों में उलटे क्रम में और हिब्रू को उलटा दिखाते हैं। टेक्स्ट पेस्ट करें और परिणाम कॉपी करें: अक्षर जुड़ जाते हैं (यूनिकोड प्रेज़ेंटेशन फ़ॉर्म) और टेक्स्ट दृश्य क्रम में आ जाता है। या कहीं भी टेक्स्ट कॉपी करें, <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> दबाएँ और पेस्ट करें।',
 demo_title='पहले और बाद में', demo_caption='दाएँ-से-बाएँ समर्थन के बिना ऐप का अनुकरण (अक्षर बाएँ से दाएँ, बिना जोड़े)। लाल: टेक्स्ट जैसा है। हरा: वही टेक्स्ट RTL Text Fixer के बाद — ऐप के असली इंजन से बना।',
 demos=['ur', 'ar', 'fa', 'he'],
 how_title='कैसे काम करता है', how=['टेक्स्ट पेस्ट करें या लिखें; लिपि और भाषा अपने-आप पहचानी जाती है।', 'प्रीव्यू दिखाता है कि परिणाम RTL समर्थन के बिना ऐप में कैसा दिखेगा। <b>परिणाम कॉपी करें</b> दबाएँ और प्रोजेक्ट में पेस्ट करें।', 'विंडो खोले बिना: टेक्स्ट कॉपी करें, <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> दबाएँ और पेस्ट करें। दोबारा दबाने पर मूल टेक्स्ट वापस आ जाता है।'],
 shot_alt='RTL Text Fixer विंडो: टेक्स्ट और ठीक किए गए टेक्स्ट का प्रीव्यू',
 langs_title='समर्थित भाषाएँ', langs='<b>अरबी लिपि वाली भाषाएँ</b> (अक्षर जोड़ना और क्रम): उर्दू, अरबी, फ़ारसी, कुर्दी (सोरानी), पश्तो, सिंधी, उइगर, लाम-अलिफ़ सहित। <b>हिब्रू और यिडिश</b> (केवल क्रम)। अंक और अंग्रेज़ी शब्द सही क्रम में रहते हैं।',
 features_title='विशेषताएँ', features=['जुड़े हुए अक्षर रूप और लाम-अलिफ़', 'दृश्य क्रम; अंक और अंग्रेज़ी शब्द सही जगह, कोष्ठक उलटे', 'लिपि और भाषा की स्वचालित पहचान', 'मात्रा-चिह्न: रखें, हटाएँ या अलग रूप', 'कई पंक्तियाँ, पंक्तियों का उलटा क्रम और पंक्ति तोड़ना', 'वापस करने का मोड', 'क्लिपबोर्ड शॉर्टकट (Ctrl+Shift+R) और ट्रे आइकन', 'हिन्दी सहित 12 भाषाओं में इंटरफ़ेस', 'ऑफ़लाइन: न अकाउंट, न विज्ञापन, न ट्रैकिंग'],
 limits_title='सीमाएँ', limits=['केवल Windows 10 (1809 या नया) और Windows 11।', 'यूनिकोड में जिन अक्षरों के जुड़े रूप नहीं हैं (जैसे कुर्दी ڵ ڕ ێ) वे अलग दिखते हैं।', 'उर्दू नस्ख़ शैली में बनती है, नस्तालीक़ में नहीं।', 'लक्ष्य ऐप के फ़ॉन्ट में अरबी प्रेज़ेंटेशन फ़ॉर्म होने चाहिए (Arial, Tahoma, Segoe UI में हैं)।'],
 faq_title='अक्सर पूछे जाने वाले प्रश्न',
 faq=[('Premiere Pro में उर्दू अक्षर अलग-अलग और उलटे क्यों दिखते हैं?', 'जो प्रोग्राम अरबी लिपि के अक्षर जोड़ने और दो-दिशात्मक टेक्स्ट का समर्थन नहीं करते, वे हर अक्षर को अलग और बाएँ से दाएँ बनाते हैं। टेक्स्ट को RTL Text Fixer से बदलें और परिणाम टाइटल में पेस्ट करें।'),
      ('Unity में हिब्रू उलटा दिखता है, क्या करें?', 'Unity के मानक टेक्स्ट कंपोनेंट दाएँ-से-बाएँ टेक्स्ट का क्रम नहीं बदलते। RTL Text Fixer से बदला हुआ टेक्स्ट Text या TextMeshPro में पेस्ट करें।'),
      ('Blender में उर्दू या अरबी कैसे लिखें?', 'Blender के टेक्स्ट ऑब्जेक्ट अरबी लिपि के अक्षर नहीं जोड़ते। RTL Text Fixer से बदला हुआ टेक्स्ट पेस्ट करें और अरबी प्रेज़ेंटेशन फ़ॉर्म वाला फ़ॉन्ट चुनें।'),
      ('क्या मेरा टेक्स्ट कहीं भेजा जाता है?', 'नहीं। ऐप पूरी तरह ऑफ़लाइन काम करता है।'),
      ('यह कहाँ मिलेगा?', 'RTL Text Fixer Microsoft Store में एक सशुल्क ऐप होगा। स्टोर पेज अभी प्रकाशित नहीं हुआ है; प्रकाशित होते ही लिंक यहाँ जोड़ा जाएगा।')],
 store_note='जल्द ही Microsoft Store पर — प्रकाशित होने पर स्टोर लिंक यहाँ जोड़ा जाएगा।', other='अन्य भाषाएँ', privacy='गोपनीयता नीति', support='सहायता',
 source_note='अक्षर जोड़ने और दिशा का डेटा यूनिकोड कैरेक्टर डेटाबेस (संस्करण 15.1) से है।')
